HERE=Path(__file__).resolve().parent; DATA=HERE/'data'; REPORTS=HERE/'reports'
captured={x['paper_id']:x for x in json.loads((DATA/'interspeech-2025-fiftyfifth-d3-papers.json').read_text())['papers']}; papers={x['paper_id']:x for x in json.loads((DATA/'interspeech-2025-papers.json').read_text())['papers']}
N={
'gu25_interspeech':('voice-generation-and-control','voice-identity-and-conversion','voice-conversion','Pitch manipulation should change intonation or musical key without destroying the underlying voice and content.', 'Pitch, source, and filter cues are entangled, and paired in-tune/out-of-tune examples are scarce.', 'Use a DSP pitch shifter or a source-filter disentanglement model trained only on paired examples.', 'Learn a pitch-independent latent representation adversarially and use cycle consistency to create the missing pairing implicitly.', 'Neurodyne encodes speech while an adversary discourages pitch information in the latent; cycle-consistency trains conversion in both directions.', 'The representation must preserve identity/content while making pitch a controllable variable, and cycle consistency supplies a constraint when aligned pairs are absent.', 'The paper reports improved global-key and template-based pitch manipulation over its compared methods.', 'Music data, pitch range, cycle assumptions, perceptual protocol, and content preservation bound transfer to conversational voice conversion.'),
'guillaume25_interspeech':('recognition-and-alignment','adaptation-and-open-vocabulary','speaker-adaptation','A speaker changes production when hearing altered feedback or interacting with another person, and one model should explain both adaptations.', 'Non-interactive feedback and interactive accommodation are often modeled separately even though both change the speaker-listener system.', 'Use unrelated models for altered-feedback production and conversational accommodation.', 'Extend a unified Bayesian perception-production framework so adaptation is an inference problem over intended and heard speech.', 'COSMO-style latent variables connect production and perception; Bayesian updating changes beliefs about the speech system under feedback or interaction.', 'Adaptation is posterior inference under uncertain sensory evidence, not merely a speaker-specific parameter fine-tune.', 'The proposal shows how both experimental paradigms can be described within one Bayesian framework.', 'This is a theoretical proposal, not an independent behavioral validation; parameterization, priors, and task fit remain open.'),
'ahmed25_interspeech':('people-variation-and-health','human-centered-evaluation','listener-effort','Speech quality should be estimated when no clean reference exists, using visual context that may help explain what is audible.', 'Audio-only proxies can miss visible articulatory or scene evidence, while PESQ/STOI are imperfect targets rather than human usefulness itself.', 'Predict a quality score from a single audio stream and treat the proxy metric as intelligibility.', 'Fuse STFT audio features with visual embeddings in a dual-branch CNN-BLSTM attention model and jointly predict PESQ and STOI.', 'The model aligns spectral and visual information before multi-task regression; LCC compares predicted and reference proxy scores under noise.', 'Multimodal evidence can improve prediction of a proxy while still inheriting the proxy’s limitations and the visual/audio distribution.', 'On LRS3-TED with DEMAND noise, the paper reports higher LCC than audio-only baselines for PESQ and STOI under seen noise.', 'Seen-noise conditions, proxy targets, visual availability, dataset, and correlation metric limit transfer; proxy prediction is not a listener study.'),
'kamo25_interspeech':('recognition-and-alignment','boundaries-and-sequence-structure','long-context-decoding','A meeting recognizer should combine systems that disagree about speaker segments, timing, and words without throwing away either signal.', 'DOVER/ROVER-style systems typically combine one output type, while meeting hypotheses disagree in both diarization and ASR boundaries.', 'Vote words independently or concatenate the best diarization and best transcript as if their time intervals matched.', 'Use MOVER’s staged alignment, segment grouping, word/timing combination, and speaker reconciliation across complete meeting hypotheses.', 'The method constructs correspondences between speaker-labeled time intervals before combining words and timings, preserving the meeting structure.', 'Combination is a structured matching problem over intervals, labels, and sequences rather than token-majority voting alone.', 'MOVER reports successful combination on CHiME-8 DASR and NOTSOFAR-1 multi-channel tasks.', 'Task formats, diarization errors, interval alignment, system diversity, and scoring rules bound transfer; fusion gains do not prove every component is complementary.'),
'dasilva25_interspeech':('listening-and-separation','source-separation-and-spatial-listening','target-conditioned-separation','A listener’s attended speaker should be isolated from a multi-talker scene using neural activity as a reference cue.', 'EEG-derived cues are noisy and indirect, and a separator that reconstructs a waveform may ignore the speech envelope that carries attention information.', 'Train only for waveform reconstruction or use an acoustic speaker cue when the target is defined neurally.', 'Train jointly to reconstruct both target waveform and target speech envelope, reinforcing the extraction mask.', 'A shared model predicts the target signal and its envelope; the dual losses constrain both fine waveform detail and slower attended-speech structure.', 'Multi-task objectives shape the latent mask toward a target defined by two related projections of the attended speaker.', 'NeuroSpex+ reports improved overall signal quality over baselines in the evaluated neuro-guided extraction setting.', 'EEG alignment, subjects, mixtures, signal metric, and lab conditions bound transfer; signal quality is not a demonstrated BCI communication benefit.'),
'chang25d_interspeech':('evaluation-and-deployment','robustness-and-system-boundary','latency-and-resource','An emotion recognizer should fit an IoT device without retaining a large private emotional-speech dataset.', 'Memory and compute constrain edge models, while emotional speech can carry sensitive information that should not be distributed unnecessarily.', 'Compress the model alone or train on a random small subset and assume it preserves the full-data decision boundary.', 'Distill a smaller synthetic dataset that retains training utility under fixed initialization, then train resource-constrained SER models on it.', 'The distilled set approximates the information needed by the learner; performance on held-out emotion recognition tests measures retained utility.', 'Data distillation shifts compression from parameters to examples, trading dataset fidelity and privacy exposure against model performance.', 'The paper reports comparable SER performance between models trained on distilled and original emotional-speech data.', 'Synthesis method, emotion labels, initialization, privacy threat model, device profile, and test split bound the result; utility parity is not formal privacy.'),
'chen25m_interspeech':('listening-and-separation','noise-enhancement','speech-prior-denoising','Reconstruct dysarthric speech so it becomes more intelligible while retaining the original speaker identity.', 'Dysarthria damages content cues and voice characteristics together; improving intelligibility can erase identity or hallucinate phonemes.', 'Enhance the waveform generically or optimize intelligibility while ignoring speaker identity.', 'Restore phoneme embeddings with a pretrained speech encoder, preserve speaker information through an identity encoder, and generate speech with latent diffusion.', 'Separate content and identity conditioning feed a diffusion generator that samples a reconstructed waveform in latent space.', 'The system imposes two invariants on generation: linguistic content must be restored while speaker identity remains in the conditioning path.', 'The paper reports improved intelligibility and speaker similarity in its dysarthric speech reconstruction evaluation.', 'Speaker, severity, reference data, perceptual metrics, and diffusion sampling bound transfer; reconstructed speech is not clinical treatment evidence.'),
'chuang25_interspeech':('languages-accents-and-resources','accent-and-cultural-boundaries','cultural-meaning','Tone realization in Taiwanese should be interpreted with word meaning and sandhi context rather than reduced to citation-tone substitution.', 'Tone sandhi changes non-final syllables and spontaneous speech varies; a raw sandhi-versus-citation comparison can mistake lexical meaning for phonological neutralization.', 'Assign one canonical tone to each lexical item or compare citation and sandhi forms without semantic context.', 'Analyze spontaneous high-falling tone realizations while modeling word meaning and compare residual sandhi/citation differences.', 'Acoustic tone measurements are grouped by lexical/semantic context, allowing meaning-induced variation to be separated from categorical tone effects.', 'The analysis treats linguistic meaning as a conditioning variable in the acoustic realization, not as nuisance variance to average away.', 'Word meaning explains part of tonal variability; after accounting for it, the reported sandhi/citation difference disappears.', 'Speaker sample, spontaneous corpus, lexical items, tone context, and statistical model bound transfer; one tone pattern is not the whole Taiwanese system.'),
}
notes=[]; claims=[]; md=['# INTERSPEECH 2025 fifty-fifth-pass full-paper notes','','Eight official-PDF readings deepen pitch/voice conversion, adaptation, human-centered evaluation, meeting alignment, neuro-guided extraction, resource limits, dysarthric reconstruction, and tonal meaning.','']
for i,(pid,f) in enumerate(N.items(),1):
 theme,sub,concept,bp,wh,naive,ap,mech,math,ww,limits=f; p=papers[pid]; c=captured[pid]
 note={'paper_id':pid,'title':p['title'],'theme_id':theme,'subtheme_id':sub,'concept_id':concept,'bp':bp,'wh':wh,'naive':naive,'ap':ap,'mech':mech,'math':math,'eval':math,'ww':ww,'limits':limits,'dots':{'theme_id':theme,'subtheme_id':sub,'concept_id':concept,'sibling_family':'batch-055'},'source':{'kind':'official-isca-archive-paper-page-plus-captured-pdf-text','pdf_sha256':c['pdf_sha256'],'full_text_sha256':c['full_text_sha256'],'pdf_path':f'data/interspeech-2025-pdfs/{pid}.pdf','text_path':c['full_text_path']},'depth':'D3','evidence_boundary':'D3 structured analyst note backed by captured PDF/text; result remains author-reported and was not independently reproduced.'}
 notes.append(note); claims.append({'claim_id':f'IS25-D3C55-{i:02d}','paper_id':pid,'subtheme':sub,'claim':ww,'evidence_depth':'D3','pdf_sha256':c['pdf_sha256'],'full_text_sha256':c['full_text_sha256'],'support_status':'paper-reported-not-independently-verified','independent_support_status':'not-established','limitations':limits})
 md += [f'## {i}. {sub}','',f"**Paper:** [{p['title']}]({p['paper_url']})",f"**Evidence:** D3; PDF SHA-256 `{c['pdf_sha256']}`; full text captured.",'']+[f'- **{label}:** {note[key]}' for label,key in zip(['Ordinary problem','Why hard','Naive attempt','Central move','Mechanism','Mathematical/conceptual structure','What paper reports','Limits'],['bp','wh','naive','ap','mech','math','ww','limits'])]+['']
(DATA/'interspeech-2025-fiftyfifth-d3-notes.json').write_text(json.dumps({'venue':'INTERSPEECH 2025','evidence_depth':'D3','notes':notes},indent=2,ensure_ascii=False)+'\n'); (DATA/'interspeech-2025-fiftyfifth-claim-ledger.json').write_text(json.dumps({'venue':'INTERSPEECH 2025','claim_count':len(claims),'claims':claims},indent=2,ensure_ascii=False)+'\n'); REPORTS.mkdir(exist_ok=True); (REPORTS/'INTERSPEECH_2025_FIFTYFIFTH_D3_NOTES.md').write_text('\n'.join(md)+'\n'); print(json.dumps({'notes':len(notes),'claims':len(claims)}))
